package cache

import (
	"fmt"
	"io"
	"net"
	"os"
	"strconv"
	"strings"
	"sync"
	"time"
)

type CacheClient struct {
	nodes       []string
	pool        map[string][]net.Conn
	mu          sync.Mutex
	maxIdle     int
	timeout     time.Duration
	useChunked  bool
	proxyMode   bool
}

type CacheRequest struct {
	Method  string
	Key     string
	Value   []byte
	Headers map[string]string
}

func NewCacheClient() *CacheClient {
	nodes := strings.Split(os.Getenv("CACHE_NODES"), ",")
	maxIdle, _ := strconv.Atoi(os.Getenv("CACHE_MAX_IDLE"))
	if maxIdle == 0 {
		maxIdle = 10
	}
	timeoutMs, _ := strconv.Atoi(os.Getenv("CACHE_TIMEOUT_MS"))
	if timeoutMs == 0 {
		timeoutMs = 5000
	}
	// When CACHE_PROXY_MODE is set, requests go through an HTTP/1.1 proxy
	proxyMode := os.Getenv("CACHE_PROXY_MODE") == "1"
	// CACHE_TRANSFER_MODE: "chunked" or "identity"
	useChunked := os.Getenv("CACHE_TRANSFER_MODE") == "chunked"

	return &CacheClient{
		nodes:      nodes,
		pool:       make(map[string][]net.Conn),
		maxIdle:    maxIdle,
		timeout:    time.Duration(timeoutMs) * time.Millisecond,
		useChunked: useChunked,
		proxyMode:  proxyMode,
	}
}

// containsCRLF reports whether s contains any CR or LF characters, which
// would allow HTTP header/request injection.
func containsCRLF(s string) bool {
	return strings.ContainsAny(s, "\r\n")
}

func (c *CacheClient) getConn(node string) (net.Conn, error) {
	c.mu.Lock()
	if conns, ok := c.pool[node]; ok && len(conns) > 0 {
		conn := conns[len(conns)-1]
		c.pool[node] = conns[:len(conns)-1]
		c.mu.Unlock()
		return conn, nil
	}
	c.mu.Unlock()
	return net.DialTimeout("tcp", node, c.timeout)
}

func (c *CacheClient) putConn(node string, conn net.Conn) {
	c.mu.Lock()
	defer c.mu.Unlock()
	if len(c.pool[node]) < c.maxIdle {
		c.pool[node] = append(c.pool[node], conn)
	} else {
		conn.Close()
	}
}

func (c *CacheClient) selectNode(key string) string {
	h := 0
	for _, ch := range key {
		h = h*31 + int(ch)
	}
	if len(c.nodes) == 0 {
		return "localhost:11211"
	}
	return c.nodes[h%len(c.nodes)]
}

// buildHTTPRequest constructs the raw HTTP/1.1 request for the cache operation.
// In proxy mode, the request is forwarded through an intermediary that may
// interpret Content-Length and Transfer-Encoding differently.
func (c *CacheClient) buildHTTPRequest(req *CacheRequest) ([]byte, error) {
	// Reject any key or header content containing CR/LF to prevent
	// HTTP header/request injection (CWE-93/CWE-113).
	if containsCRLF(req.Key) {
		return nil, fmt.Errorf("invalid cache key: contains CR/LF")
	}
	if containsCRLF(req.Method) {
		return nil, fmt.Errorf("invalid method: contains CR/LF")
	}
	for k, v := range req.Headers {
		if containsCRLF(k) || containsCRLF(v) {
			return nil, fmt.Errorf("invalid header %q: contains CR/LF", k)
		}
	}

	var buf strings.Builder
	path := fmt.Sprintf("/cache/%s", req.Key)
	buf.WriteString(fmt.Sprintf("%s %s HTTP/1.1\r\n", req.Method, path))
	buf.WriteString(fmt.Sprintf("Host: cache-service\r\n"))
	buf.WriteString("Connection: keep-alive\r\n")

	for k, v := range req.Headers {
		buf.WriteString(fmt.Sprintf("%s: %s\r\n", k, v))
	}

	if req.Value != nil && len(req.Value) > 0 {
		if c.proxyMode && c.useChunked {
			// In proxy+chunked mode, use only Transfer-Encoding
			// per RFC 7230 Section 3.3.2: A sender MUST NOT send
			// both Content-Length and Transfer-Encoding.
			buf.WriteString("Transfer-Encoding: chunked\r\n")
			buf.WriteString("\r\n")
			// Write chunked body
			buf.WriteString(fmt.Sprintf("%x\r\n", len(req.Value)))
			buf.Write(req.Value)
			buf.WriteString("\r\n0\r\n\r\n")
		} else if c.useChunked {
			buf.WriteString("Transfer-Encoding: chunked\r\n")
			buf.WriteString("\r\n")
			buf.WriteString(fmt.Sprintf("%x\r\n", len(req.Value)))
			buf.Write(req.Value)
			buf.WriteString("\r\n0\r\n\r\n")
		} else {
			buf.WriteString(fmt.Sprintf("Content-Length: %d\r\n", len(req.Value)))
			buf.WriteString("\r\n")
			buf.Write(req.Value)
		}
	} else {
		buf.WriteString("\r\n")
	}

	return []byte(buf.String()), nil
}

func (c *CacheClient) Do(req *CacheRequest) ([]byte, error) {
	node := c.selectNode(req.Key)
	conn, err := c.getConn(node)
	if err != nil {
		return nil, fmt.Errorf("connection failed: %w", err)
	}

	rawReq, err := c.buildHTTPRequest(req)
	if err != nil {
		conn.Close()
		return nil, fmt.Errorf("invalid request: %w", err)
	}
	conn.SetWriteDeadline(time.Now().Add(c.timeout))
	_, err = conn.Write(rawReq)
	if err != nil {
		conn.Close()
		return nil, fmt.Errorf("write failed: %w", err)
	}

	conn.SetReadDeadline(time.Now().Add(c.timeout))
	respBuf := make([]byte, 4096)
	n, err := conn.Read(respBuf)
	if err != nil && err != io.EOF {
		conn.Close()
		return nil, fmt.Errorf("read failed: %w", err)
	}

	// Return connection to pool for reuse
	c.putConn(node, conn)
	return respBuf[:n], nil
}

func (c *CacheClient) Set(key string, value []byte) error {
	_, err := c.Do(&CacheRequest{
		Method:  "PUT",
		Key:     key,
		Value:   value,
		Headers: map[string]string{},
	})
	return err
}

func (c *CacheClient) Get(key string) ([]byte, error) {
	return c.Do(&CacheRequest{
		Method:  "GET",
		Key:     key,
		Headers: map[string]string{},
	})
}
